"use client";

import type { ReactNode } from "react";
import { useCallback, useMemo, useState } from "react";

import { Chip } from "../../base/badges/chip";
import { useCountUp } from "../../hooks/use-count-up";
import { cx } from "../../utils/cx";
import { CardSurface } from "./card-surface";

/**
 * The frame every chart card in the system shares.
 *
 * The cards differ only in the mark they draw, so everything around the mark
 * lives here once: the 344px surface, the header that swaps its headline for
 * whatever the pointer is over, the count-up figure, the delta chip and the
 * legend. A new chart is then a component that renders a Recharts (or SVG)
 * mark and hands this its numbers — which is why the family stays consistent
 * as it grows.
 */

export type DeltaColor = "lime" | "rose" | "neutral";

export interface ChartDelta {
  label: string;
  color: DeltaColor;
}

/** Percentage change from `previous` to `current`, as a chip-ready label. */
export function describeDelta(current: number, previous: number): ChartDelta {
  if (previous === 0) return { label: "New", color: "neutral" };
  const change = ((current - previous) / previous) * 100;
  const rounded = Math.round(change * 10) / 10;
  if (rounded === 0) return { label: "0%", color: "neutral" };
  return {
    label: `${rounded > 0 ? "+" : ""}${rounded}%`,
    color: rounded > 0 ? "lime" : "rose",
  };
}

/** Compact axis labels: 1200 → 1.2k, 1_400_000 → 1.4M. */
export function formatCompact(value: number, prefix = ""): string {
  const abs = Math.abs(value);
  if (abs >= 1_000_000) return `${prefix}${Math.round(value / 100_000) / 10}M`;
  if (abs >= 1_000) return `${prefix}${Math.round(value / 100) / 10}k`;
  return `${prefix}${value}`;
}

/** Thousands-separated, no decimals — the headline format. */
export function formatNumber(value: number): string {
  return value.toLocaleString("en-US", { maximumFractionDigits: 0 });
}

/**
 * What Recharts hands its chart-level mouse handlers.
 *
 * Kept structural rather than imported: Recharts types `activeTooltipIndex` as
 * `number | TooltipIndex`, where `TooltipIndex` is `string | null`, so the
 * index arrives as a string on some charts and has to be coerced either way.
 */
interface ChartMouseState {
  isTooltipActive?: boolean;
  activeTooltipIndex?: number | string | null;
}

/**
 * Shared hover state for a chart's active index.
 *
 * Recharts reports the active index on the chart element rather than per mark,
 * so every card wires the same two handlers; this keeps that in one place.
 */
export function useChartHover() {
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const handlers = useMemo(
    () => ({
      onMouseMove: (state: ChartMouseState) => {
        const index = Number(state?.activeTooltipIndex);
        if (state?.isTooltipActive === true && Number.isFinite(index))
          setActiveIndex(index);
      },
      onMouseLeave: () => setActiveIndex(null),
    }),
    [],
  );

  const clear = useCallback(() => setActiveIndex(null), []);

  return { activeIndex, setActiveIndex, handlers, clear };
}

export interface ChartLegendEntry {
  label: string;
  value?: ReactNode;
  /** Any CSS colour — usually `var(--color-chart-N-active)`. */
  color: string;
  /** Draw a dashed rule instead of a dot, for comparison series. */
  dashed?: boolean;
}

export function ChartLegend({
  entries,
  variant = "compact",
}: {
  entries: ChartLegendEntry[];
  variant?: "compact" | "summary";
}) {
  return (
    <dl
      className={cx(
        "flex shrink-0 flex-wrap items-center gap-4 text-text-secondary",
        variant === "summary"
          ? "justify-center text-body-regular"
          : "text-body-2-medium",
      )}
    >
      {entries.map((entry) => (
        <div key={entry.label} className="flex items-center gap-1.5">
          {entry.dashed === true ? (
            <span
              className="h-0 w-3.5 border-t-2 border-dashed"
              style={{ borderColor: entry.color }}
              aria-hidden
            />
          ) : (
            <span
              className="size-2 rounded-full"
              style={{ backgroundColor: entry.color }}
              aria-hidden
            />
          )}
          <dt>{entry.label}</dt>
          {entry.value !== undefined && (
            <dd className="text-text-primary">{entry.value}</dd>
          )}
        </div>
      ))}
    </dl>
  );
}

export interface ChartCardProps {
  /** Sits above the headline; swap it for the hovered point's own label. */
  label: string;
  /** The headline number. Counts up when it changes. */
  value: number;
  /** Rendered around the counted value, e.g. `$` or `%`. */
  prefix?: string;
  suffix?: string;
  /** Delta chip beside the headline. Omit for no chip. */
  delta?: ChartDelta;
  /** The quiet line under the headline — usually what it is being compared to. */
  caption?: string;
  legend?: ChartLegendEntry[];
  /** Anything to the right of the header instead of a legend — a control, say. */
  action?: ReactNode;
  /** Re-triggers the headline's fade when it changes; pass the active index. */
  pulseKey?: string | number | null;
  /** Format the counted headline value. */
  formatValue?: (value: number) => string;
  /** Keep fractional values for a custom formatter. Defaults to integer counting. */
  roundValue?: boolean;
  children: ReactNode;
  className?: string;
  /** Default 344px, matching the dashboard row. */
  height?: number | "auto";
}

export function ChartCard({
  label,
  value,
  prefix = "",
  suffix = "",
  delta,
  caption,
  legend,
  action,
  pulseKey = null,
  formatValue = formatNumber,
  roundValue = true,
  children,
  className,
  height = 344,
}: ChartCardProps) {
  const display = useCountUp(
    roundValue ? Math.round(value) : value,
    320,
    roundValue,
  );

  return (
    <CardSurface
      className={cx("flex min-w-0 flex-1 flex-col gap-6", className)}
      style={height === "auto" ? undefined : { height }}
    >
      <div className="flex w-full flex-col gap-3 sm:flex-row sm:items-start sm:gap-0.5">
        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{label}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={pulseKey ?? "total"}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              {prefix}
              {formatValue(display)}
              {suffix}
            </p>
            {delta !== undefined && (
              <Chip variant="bold" color={delta.color}>
                {delta.label}
              </Chip>
            )}
          </div>
          {caption !== undefined && (
            <p className="text-body-2-medium text-text-tertiary tabular-nums">
              {caption}
            </p>
          )}
        </div>

        {action ?? (legend !== undefined && <ChartLegend entries={legend} />)}
      </div>

      <div className="min-h-0 w-full flex-1">{children}</div>
    </CardSurface>
  );
}

/** Axis styling every Recharts card shares. */
export const AXIS = {
  tickLine: false,
  axisLine: false,
  tick: { fontSize: 12, fill: "var(--color-text-tertiary)" },
} as const;

/** The dashed vertical rule Recharts draws under the pointer. */
export const CURSOR = {
  stroke: "var(--color-chart-cursor)",
  strokeWidth: 1,
  strokeDasharray: "4 4",
} as const;

import type { ComponentPropsWithRef } from "react";
import { cx } from "../../utils/cx";

/** Shared card paint and insets; each composition owns its layout and content. */
export type CardPadding = "chart" | "uniform" | "inset" | "none";
export interface CardSurfaceOptions {
  padding?: CardPadding;
  tone?: "primary" | "secondary" | "full";
}
/** Shared paint for native and animated card roots. */
export function cardSurfaceClasses({
  padding = "chart",
  tone = "secondary",
}: CardSurfaceOptions = {}) {
  return cx(
    "rounded-2xl",
    tone === "full"
      ? "bg-background-full"
      : tone === "primary"
      ? "bg-background-primary-default"
      : "bg-background-secondary-default",
    padding === "none"
      ? undefined
      : padding === "inset"
        ? "p-2.5"
        : padding === "uniform"
          ? "p-4"
          : "px-4 pt-4 pb-3",
  );
}
export function CardSurface({
  className,
  padding = "chart",
  tone = "secondary",
  ...props
}: ComponentPropsWithRef<"section"> & CardSurfaceOptions) {
  return (
    <section
      {...props}
      className={cx(cardSurfaceClasses({ padding, tone }), className)}
    />
  );
}

// @zeus-internal
"use client";

import type { HTMLAttributes, ReactNode } from "react";
import { Button, type ButtonProps } from "react-aria-components";
import { Tooltip, TooltipTrigger } from "../../base/tooltip/tooltip";
import { cx } from "../../utils/cx";

/** Focusable chart mark with the shared tooltip and focus treatment. */
export function ChartCell({
  tooltip,
  className,
  ...props
}: Omit<ButtonProps, "children" | "className"> & {
  tooltip: ReactNode;
  className?: string;
}) {
  return (
    <TooltipTrigger>
      <Button
        {...props}
        className={cx(
          "cursor-default outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
          className,
        )}
      />
      <Tooltip>{tooltip}</Tooltip>
    </TooltipTrigger>
  );
}

/** A chart swatch is descriptive by default; consumers can opt into keyboard inspection. */
export function ChartSwatch({
  focusable = false,
  onInspect,
  className,
  ...props
}: Omit<
  HTMLAttributes<HTMLElement>,
  "children" | "onFocus" | "onBlur" | "onMouseEnter" | "onMouseLeave"
> & {
  focusable?: boolean;
  onInspect?: (active: boolean) => void;
}) {
  const handlers = {
    onMouseEnter: () => onInspect?.(true),
    onMouseLeave: () => onInspect?.(false),
  };
  return focusable ? (
    <button
      {...props}
      {...handlers}
      type="button"
      onFocus={() => onInspect?.(true)}
      onBlur={() => onInspect?.(false)}
      className={cx(
        "outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
        className,
      )}
    />
  ) : (
    <div {...props} {...handlers} role="img" className={className} />
  );
}

/** HTML-axis labels share the same type and inspected-colour transition. */
export function ChartAxisLabel({
  active = false,
  className,
  ...props
}: HTMLAttributes<HTMLSpanElement> & { active?: boolean }) {
  return (
    <span
      {...props}
      className={cx(
        "text-caption-1-medium transition-colors duration-150 ease-out",
        active ? "text-text-primary" : "text-text-tertiary",
        className,
      )}
    />
  );
}

// @zeus-internal
/** Shared track and hover outline for vertical bar marks. */
export function ChartBarTrack({
  x = 0,
  y = 0,
  width = 0,
  height = 0,
  active,
  className,
}: {
  x?: number | string;
  y?: number | string;
  width?: number | string;
  height?: number | string;
  active: boolean;
  className?: string;
}) {
  return (
    <g className={className}>
      <rect
        x={x}
        y={y}
        width={width}
        height={height}
        rx={10}
        ry={10}
        fill="var(--color-chart-track)"
      />
      <rect
        className="transition-opacity duration-150 ease-out"
        x={Number(x) - 3}
        y={Number(y) - 3}
        width={Number(width) + 6}
        height={Number(height) + 6}
        rx={13}
        ry={13}
        fill="none"
        stroke="var(--color-chart-cursor)"
        strokeWidth={2}
        opacity={active ? 1 : 0}
      />
    </g>
  );
}

// @zeus-internal
"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";

/** Measures the available plot in CSS pixels, independently of preview transforms. */
export function ChartPlot({
  children,
  roundDimensions = false,
}: {
  roundDimensions?: boolean;
  children: (size: { width: number; height: number }) => ReactNode;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [size, setSize] = useState({ width: 0, height: 0 });
  useEffect(() => {
    if (!ref.current) return;
    const observer = new ResizeObserver(([entry]) => {
      if (!entry) return;
      const width = roundDimensions ? Math.round(entry.contentRect.width) : entry.contentRect.width;
      const height = roundDimensions
        ? Math.round(entry.contentRect.height)
        : entry.contentRect.height;
      if (width > 0 && height > 0)
        setSize((previous) =>
          previous.width === width && previous.height === height ? previous : { width, height },
        );
    });
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [roundDimensions]);
  return (
    <div ref={ref} className="relative min-h-0 w-full flex-1">
      {size.width > 0 && children(size)}
    </div>
  );
}

// @zeus-internal
"use client";

import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";

/** Shared chart inspection point with a linear expanding halo. */
export function ChartActiveDot({
  cx,
  cy,
  fill,
  pulse = true,
  coreRadius = 5,
  coreStrokeWidth = 3,
}: {
  cx?: number;
  cy?: number;
  fill?: string;
  pulse?: boolean;
  coreRadius?: number;
  coreStrokeWidth?: number;
}) {
  const reduced = useHydratedReducedMotion();
  if (cx == null || cy == null) return null;
  return (
    <g>
      {pulse && (
        <circle cx={cx} cy={cy} r={5} fill={fill} opacity={0.3}>
          {!reduced && (
            <>
              <animate
                attributeName="r"
                values="5;13"
                dur="1.4s"
                repeatCount="indefinite"
              />
              <animate
                attributeName="opacity"
                values="0.35;0"
                dur="1.4s"
                repeatCount="indefinite"
              />
            </>
          )}
        </circle>
      )}
      <circle
        cx={cx}
        cy={cy}
        r={coreRadius}
        fill={fill}
        stroke="var(--color-background-secondary-default)"
        strokeWidth={coreStrokeWidth}
        className={pulse ? undefined : "recharts-dot"}
      />
    </g>
  );
}
